"use client";

import { useEffect, useMemo, useRef } from "react";
/**
 * `<Whiteboard>` — view-only primitive that turns a JSON scene into a
 * hand-drawn SVG. Lives in the isolated subpath `@theokit/ui/whiteboard`.
 *
 * See RFC 0001 (`docs/rfcs/0001-whiteboard.md`) and the plan in
 * `.claude/knowledge-base/plans/whiteboard-view-primitive-plan.md`.
 */
import rough from "roughjs";
import type { RoughGenerator } from "roughjs/bin/generator";
import { renderScene } from "@/components/ui/whiteboard/render/scene";
import type { WhiteboardScene, WhiteboardSceneInput } from "@/components/ui/whiteboard/schema";
import { type ValidationError, validateScene } from "@/components/ui/whiteboard/validate";
import { usePointerPan } from "@/components/ui/whiteboard/viewport/use-pointer-pan";
import { useViewport } from "@/components/ui/whiteboard/viewport/use-viewport";

/** Input type accepted by the component (defaults like `headEnd` are optional). */
export type WhiteboardData = WhiteboardSceneInput;
export type { ValidationError } from "@/components/ui/whiteboard/validate";

export interface WhiteboardProps {
  /** The scene to render. Validated with Zod on every change. */
  data: WhiteboardData | unknown;
  className?: string;
  /** Starting zoom level (clamped 0.1–8). Default 1. */
  initialZoom?: number;
  /** World coordinate centered in the viewport on first render. */
  initialCenter?: [number, number];
  /** When true, computes a bounding box of all elements and zooms to fit. */
  fitOnLoad?: boolean;
  /** Called once per validation failure with the list of errors (EC-6: in useEffect, not render). */
  onValidationError?: (errors: ValidationError[]) => void;
  /** Accessible label for the SVG (defaults to "Whiteboard diagram"). */
  "aria-label"?: string;
}

function computeBounds(scene: WhiteboardScene): {
  minX: number;
  minY: number;
  maxX: number;
  maxY: number;
} | null {
  if (scene.elements.length === 0) return null;
  let minX = Number.POSITIVE_INFINITY;
  let minY = Number.POSITIVE_INFINITY;
  let maxX = Number.NEGATIVE_INFINITY;
  let maxY = Number.NEGATIVE_INFINITY;
  for (const el of scene.elements) {
    const x1 = el.x;
    const y1 = el.y;
    let x2 = el.x;
    let y2 = el.y;
    if (el.type === "rect" || el.type === "ellipse" || el.type === "diamond") {
      x2 = el.x + el.w;
      y2 = el.y + el.h;
    } else if (el.type === "line" || el.type === "arrow") {
      x2 = el.to[0];
      y2 = el.to[1];
    } else if (el.type === "freedraw") {
      for (const [px, py] of el.points) {
        const tx = el.x + px;
        const ty = el.y + py;
        if (tx < minX) minX = tx;
        if (ty < minY) minY = ty;
        if (tx > maxX) maxX = tx;
        if (ty > maxY) maxY = ty;
      }
      continue;
    }
    if (x1 < minX) minX = x1;
    if (y1 < minY) minY = y1;
    if (x2 < minX) minX = x2;
    if (y2 < minY) minY = y2;
    if (x1 > maxX) maxX = x1;
    if (y1 > maxY) maxY = y1;
    if (x2 > maxX) maxX = x2;
    if (y2 > maxY) maxY = y2;
  }
  if (!Number.isFinite(minX)) return null;
  return { minX, minY, maxX, maxY };
}

export function Whiteboard({
  data,
  className,
  initialZoom,
  initialCenter,
  fitOnLoad,
  onValidationError,
  "aria-label": ariaLabel,
}: WhiteboardProps) {
  const validation = useMemo(() => validateScene(data), [data]);
  const scene = validation.ok ? validation.scene : null;

  // EC-6: side effects only inside useEffect — never call user callbacks in render.
  useEffect(() => {
    if (!validation.ok && onValidationError) {
      onValidationError(validation.errors);
    }
  }, [validation, onValidationError]);

  // Stable rough.js generator across renders.
  const generator: RoughGenerator | null = useMemo(() => {
    if (typeof globalThis === "undefined") return null;
    try {
      return rough.generator();
    } catch {
      return null;
    }
  }, []);

  // Fallback dimensions for invalid scenes (still render a valid svg).
  const sceneWidth = scene?.width ?? 400;
  const sceneHeight = scene?.height ?? 300;
  const sceneBackground = scene?.background;

  const viewport = useViewport({
    width: sceneWidth,
    height: sceneHeight,
    initialZoom,
    initialCenter,
  });

  const svgRef = useRef<SVGSVGElement | null>(null);

  const fitTo = viewport.fitTo;
  // EC-14: fitOnLoad must run in useEffect (after mount), not during render.
  useEffect(() => {
    if (!fitOnLoad || !scene) return;
    const bounds = computeBounds(scene);
    if (!bounds) return;
    fitTo(bounds, { width: sceneWidth, height: sceneHeight });
  }, [fitOnLoad, scene, sceneWidth, sceneHeight, fitTo]);

  const handlers = usePointerPan(svgRef, viewport, {
    width: sceneWidth,
    height: sceneHeight,
  });

  const label = ariaLabel ?? "Whiteboard diagram";

  return (
    <svg
      data-slot="whiteboard"
      ref={svgRef}
      viewBox={viewport.viewBox({ width: sceneWidth, height: sceneHeight })}
      width={sceneWidth}
      height={sceneHeight}
      className={className}
      role="img"
      aria-label={label}
      xmlns="http://www.w3.org/2000/svg"
      data-whiteboard-state={scene ? "ok" : "invalid"}
      style={{ touchAction: "none", userSelect: "none" }}
      {...handlers}
    >
      <title>{label}</title>
      {sceneBackground ? (
        <rect
          x={0}
          y={0}
          width={sceneWidth}
          height={sceneHeight}
          fill={sceneBackground}
          data-layer="background"
        />
      ) : null}
      {scene && generator ? renderScene(scene, generator) : null}
    </svg>
  );
}

/**
 * Zod schema for the Whiteboard JSON v1 (`WhiteboardScene`).
 *
 * Design goals (see RFC 0001 §4 and ADR D4 in the plan):
 *   - LLM-friendly: minimal fields per element.
 *   - Discriminated union by `type` for exhaustive typing in TS.
 *   - Defensive against LLM mistakes:
 *     - EC-3: `.finite()` everywhere — rejects NaN / Infinity.
 *     - EC-4: `.max()` on dimensions to cap absurd values from the model.
 */
import { z } from "zod";

const finiteNumber = z.number().finite();
const finitePositive = finiteNumber.positive();

const strokeStyle = z.enum(["solid", "dashed", "dotted"]);
const fillStyle = z.enum(["hachure", "solid", "cross-hatch", "zigzag"]);
const align = z.enum(["left", "center", "right"]);
const fontFamily = z.enum(["sans", "serif", "mono", "hand"]);
const roundness = z.enum(["sharp", "round"]);

const baseElement = z.object({
  id: z.string().max(120).optional(),
  x: finiteNumber,
  y: finiteNumber,
  stroke: z.string().max(64).optional(),
  strokeWidth: finitePositive.max(50).optional(),
  strokeStyle: strokeStyle.optional(),
  fill: z.string().max(64).optional(),
  fillStyle: fillStyle.optional(),
  opacity: finiteNumber.min(0).max(1).optional(),
  roughness: finiteNumber.min(0).max(3).optional(),
  seed: z.number().int().finite().optional(),
});

const dim = finitePositive.max(20000);
const labelText = z.string().max(500);

const rectElement = baseElement.extend({
  type: z.literal("rect"),
  w: dim,
  h: dim,
  label: labelText.optional(),
  roundness: roundness.optional(),
});

const ellipseElement = baseElement.extend({
  type: z.literal("ellipse"),
  w: dim,
  h: dim,
  label: labelText.optional(),
});

const diamondElement = baseElement.extend({
  type: z.literal("diamond"),
  w: dim,
  h: dim,
  label: labelText.optional(),
});

const point2 = z.tuple([finiteNumber, finiteNumber]);

const lineElement = baseElement.extend({
  type: z.literal("line"),
  to: point2,
});

const arrowElement = baseElement.extend({
  type: z.literal("arrow"),
  to: point2,
  label: labelText.optional(),
  headStart: z.boolean().optional(),
  headEnd: z.boolean().default(true),
});

const textElement = baseElement.extend({
  type: z.literal("text"),
  text: z.string().max(5000),
  fontSize: finitePositive.max(500).optional(),
  align: align.optional(),
  fontFamily: fontFamily.optional(),
});

const freedrawPoint = z.tuple([finiteNumber, finiteNumber, finiteNumber.optional()]);

const freedrawElement = baseElement.extend({
  type: z.literal("freedraw"),
  points: z.array(freedrawPoint).min(2).max(5000),
});

export const whiteboardElement = z.discriminatedUnion("type", [
  rectElement,
  ellipseElement,
  diamondElement,
  lineElement,
  arrowElement,
  textElement,
  freedrawElement,
]);

export const whiteboardScene = z.object({
  version: z.literal(1),
  width: dim, // EC-4: clamped 1..20000
  height: dim, // EC-4: clamped 1..20000
  background: z.string().max(64).optional(),
  elements: z.array(whiteboardElement).max(5000),
});

// Internal "parsed" types (defaults applied) — used inside the renderer.
export type WhiteboardElement = z.output<typeof whiteboardElement>;
export type WhiteboardScene = z.output<typeof whiteboardScene>;
export type RectElement = z.output<typeof rectElement>;
export type EllipseElement = z.output<typeof ellipseElement>;
export type DiamondElement = z.output<typeof diamondElement>;
export type LineElement = z.output<typeof lineElement>;
export type ArrowElement = z.output<typeof arrowElement>;
export type TextElement = z.output<typeof textElement>;
export type FreedrawElement = z.output<typeof freedrawElement>;

// Public "input" types (defaults optional) — used by consumers passing data.
export type WhiteboardElementInput = z.input<typeof whiteboardElement>;
export type WhiteboardSceneInput = z.input<typeof whiteboardScene>;

/**
 * Public validator for `WhiteboardScene` JSON. Wraps Zod and converts errors
 * into a structured shape that an LLM can consume to self-correct.
 *
 * Returns `{ ok: true, scene }` on success or `{ ok: false, errors }` with
 * each error carrying `{ path, message, code, got? }`. See RFC 0001 §4.
 */
import { type WhiteboardScene, whiteboardScene } from "@/components/ui/whiteboard/schema";

export interface ValidationError {
  /** Dot-joined Zod path, e.g. "elements.2.type" or "width". */
  path: string;
  /** Human-readable explanation (passes through Zod's message). */
  message: string;
  /** Zod issue code: `invalid_type`, `too_small`, `invalid_literal`, ... */
  code: string;
  /** Actual value received at `path`. Populated for type mismatches, discriminator mismatches, and any issue where Zod's `received` is absent but the value can be recovered by walking the original input along `path`. */
  got?: unknown;
}

export type ValidationResult =
  | { ok: true; scene: WhiteboardScene }
  | { ok: false; errors: ValidationError[] };

interface ZodLikeIssue {
  path: ReadonlyArray<string | number>;
  message: string;
  code: string;
  received?: unknown;
}

/** Walk `input` following the issue path and return the offending value. */
function valueAtPath(input: unknown, path: ReadonlyArray<string | number>): unknown {
  let cursor: unknown = input;
  for (const segment of path) {
    if (cursor === null || typeof cursor !== "object") return undefined;
    cursor = (cursor as Record<string | number, unknown>)[segment];
  }
  return cursor;
}

function formatIssue(issue: ZodLikeIssue, input: unknown): ValidationError {
  const error: ValidationError = {
    path: issue.path.join("."),
    message: issue.message,
    code: issue.code,
  };
  // Populate `got` from the issue when Zod provides it (invalid_type), or by
  // walking the original input along the path (invalid_union / invalid_value).
  // LLM auto-correction benefits from seeing what was actually emitted.
  if ("received" in issue && issue.received !== undefined) {
    error.got = issue.received;
  } else if (issue.path.length > 0) {
    const value = valueAtPath(input, issue.path);
    if (value !== undefined) error.got = value;
  }
  return error;
}

export function validateScene(input: unknown): ValidationResult {
  const result = whiteboardScene.safeParse(input);
  if (result.success) {
    return { ok: true, scene: result.data };
  }
  const errors = result.error.issues.map((issue) =>
    formatIssue(issue as unknown as ZodLikeIssue, input),
  );
  return { ok: false, errors };
}

/**
 * Deterministic seed derivation for rough.js — see ADR D9.
 *
 * rough.js uses pseudo-randomness to produce the hand-drawn look. Without a
 * stable seed every render shifts the strokes slightly, breaking snapshot
 * tests, causing SSR hydration mismatches, and visible jitter when the parent
 * re-renders. FNV-1a 32-bit gives us a fast, dependency-free hash.
 */

const FNV_OFFSET_BASIS_32 = 0x811c9dc5;
const FNV_PRIME_32 = 0x01000193;

/** FNV-1a 32-bit hash. Returns a signed 32-bit integer. */
export function fnv1a32(input: string): number {
  let hash = FNV_OFFSET_BASIS_32;
  for (let i = 0; i < input.length; i++) {
    hash ^= input.charCodeAt(i);
    // Multiply by the FNV prime, but keep within 32-bit unsigned range.
    hash = Math.imul(hash, FNV_PRIME_32);
  }
  // Cast to signed 32-bit via `| 0`.
  return hash | 0;
}

interface SeedableShape {
  type: string;
  x: number;
  y: number;
  w?: number;
  h?: number;
  label?: string;
  seed?: number;
}

/** Return the element's explicit `seed` or derive a stable one from its props. */
export function deriveSeed(el: SeedableShape): number {
  if (typeof el.seed === "number" && Number.isFinite(el.seed)) {
    return el.seed | 0;
  }
  // Compose a key from the dimensions that visually define the shape. Other
  // fields (colors, opacity) don't change the underlying rough.js geometry.
  const key = `${el.type}|${el.x}|${el.y}|${el.w ?? ""}|${el.h ?? ""}|${el.label ?? ""}`;
  return fnv1a32(key);
}

import type { RoughGenerator } from "roughjs/bin/generator";
import type { WhiteboardElement, WhiteboardScene } from "@/components/ui/whiteboard/schema";
import { deriveSeed } from "@/components/ui/whiteboard/seed";
import { renderFreedraw } from "@/components/ui/whiteboard/render/freedraw";
import { renderArrow, renderLine } from "@/components/ui/whiteboard/render/line";
import { renderDiamond, renderEllipse, renderRect } from "@/components/ui/whiteboard/render/shape";
import { renderText } from "@/components/ui/whiteboard/render/text";

function elementWithSeed<T extends WhiteboardElement>(el: T): T {
  if (typeof el.seed === "number") return el;
  return { ...el, seed: deriveSeed(el) } as T;
}

function renderElement(el: WhiteboardElement, gen: RoughGenerator): React.ReactNode {
  switch (el.type) {
    case "rect":
      return renderRect(gen, elementWithSeed(el));
    case "ellipse":
      return renderEllipse(gen, elementWithSeed(el));
    case "diamond":
      return renderDiamond(gen, elementWithSeed(el));
    case "line":
      return renderLine(gen, elementWithSeed(el));
    case "arrow":
      return renderArrow(gen, elementWithSeed(el));
    case "text":
      return renderText(elementWithSeed(el));
    case "freedraw":
      return renderFreedraw(elementWithSeed(el));
  }
}

export function renderScene(scene: WhiteboardScene, gen: RoughGenerator): React.ReactNode {
  return (
    <>
      {scene.elements.map((el, i) => (
        <g
          key={el.id ?? `__idx-${i}`}
          data-element-id={el.id ?? String(i)}
          data-element-type={el.type}
        >
          {renderElement(el, gen)}
        </g>
      ))}
    </>
  );
}

import type { RoughGenerator } from "roughjs/bin/generator";
import type { DiamondElement, EllipseElement, RectElement } from "@/components/ui/whiteboard/schema";
import { toRoughPaths } from "@/components/ui/whiteboard/render/rough-paths";
import { buildOptions, strokeDashArray } from "@/components/ui/whiteboard/render/style";

interface LabelProps {
  cx: number;
  cy: number;
  label: string;
  stroke?: string;
}

function Label({ cx, cy, label, stroke }: LabelProps) {
  return (
    <text
      data-slot="label"
      x={cx}
      y={cy}
      textAnchor="middle"
      dominantBaseline="central"
      fontSize={16}
      fontFamily="ui-sans-serif, system-ui, sans-serif"
      fill={stroke ?? "currentColor"}
      style={{ pointerEvents: "none" }}
    >
      {label}
    </text>
  );
}

function pathsToReactNodes(
  paths: ReturnType<typeof toRoughPaths>,
  keyPrefix: string,
  outlineStroke: string,
  dashArray?: string,
): React.ReactNode[] {
  return paths.map((p, i) => {
    // Apply stroke-dasharray only to paths whose stroke matches the outline
    // color — this avoids dashing hachure/cross-hatch fill lines (which are
    // stroked in the fill color, not the outline color) when a shape mixes
    // fillStyle with strokeStyle.
    const isOutline = p.stroke === outlineStroke;
    return (
      <path
        // biome-ignore lint/suspicious/noArrayIndexKey: rough.js path order is stable for a given (geometry, seed) tuple — index is the most precise key.
        key={`${keyPrefix}-${i}`}
        d={p.d}
        stroke={p.stroke}
        strokeWidth={p.strokeWidth}
        fill={p.fill ?? "none"}
        strokeLinecap="round"
        strokeLinejoin="round"
        strokeDasharray={isOutline ? dashArray : undefined}
      />
    );
  });
}

export function renderRect(gen: RoughGenerator, el: RectElement): React.ReactNode {
  const opts = buildOptions(el, el.seed ?? 0);
  const drawable = gen.rectangle(el.x, el.y, el.w, el.h, opts);
  const paths = toRoughPaths(gen, drawable);
  const dash = strokeDashArray(el.strokeStyle, el.strokeWidth ?? 1.5);
  return (
    <g opacity={el.opacity ?? 1}>
      {pathsToReactNodes(paths, "rect", opts.stroke as string, dash)}
      {el.label ? (
        <Label cx={el.x + el.w / 2} cy={el.y + el.h / 2} label={el.label} stroke={el.stroke} />
      ) : null}
    </g>
  );
}

export function renderEllipse(gen: RoughGenerator, el: EllipseElement): React.ReactNode {
  const opts = buildOptions(el, el.seed ?? 0);
  // rough.js ellipse takes center + width + height.
  const drawable = gen.ellipse(el.x + el.w / 2, el.y + el.h / 2, el.w, el.h, opts);
  const paths = toRoughPaths(gen, drawable);
  const dash = strokeDashArray(el.strokeStyle, el.strokeWidth ?? 1.5);
  return (
    <g opacity={el.opacity ?? 1}>
      {pathsToReactNodes(paths, "ellipse", opts.stroke as string, dash)}
      {el.label ? (
        <Label cx={el.x + el.w / 2} cy={el.y + el.h / 2} label={el.label} stroke={el.stroke} />
      ) : null}
    </g>
  );
}

export function renderDiamond(gen: RoughGenerator, el: DiamondElement): React.ReactNode {
  const opts = buildOptions(el, el.seed ?? 0);
  const cx = el.x + el.w / 2;
  const cy = el.y + el.h / 2;
  const points: [number, number][] = [
    [cx, el.y], // top
    [el.x + el.w, cy], // right
    [cx, el.y + el.h], // bottom
    [el.x, cy], // left
  ];
  const drawable = gen.polygon(points, opts);
  const paths = toRoughPaths(gen, drawable);
  const dash = strokeDashArray(el.strokeStyle, el.strokeWidth ?? 1.5);
  return (
    <g opacity={el.opacity ?? 1}>
      {pathsToReactNodes(paths, "diamond", opts.stroke as string, dash)}
      {el.label ? <Label cx={cx} cy={cy} label={el.label} stroke={el.stroke} /> : null}
    </g>
  );
}

import type { RoughGenerator } from "roughjs/bin/generator";
import type { ArrowElement, LineElement } from "@/components/ui/whiteboard/schema";
import { toRoughPaths } from "@/components/ui/whiteboard/render/rough-paths";
import { buildOptions, strokeDashArray } from "@/components/ui/whiteboard/render/style";

const HEAD_BASE_PX = 12;
const HEAD_ANGLE_RAD = Math.PI / 7; // ~25°

interface HeadGeom {
  apexX: number;
  apexY: number;
  leftX: number;
  leftY: number;
  rightX: number;
  rightY: number;
}

function arrowHeadGeometry(
  fromX: number,
  fromY: number,
  toX: number,
  toY: number,
  strokeWidth: number,
): HeadGeom | null {
  const dx = toX - fromX;
  const dy = toY - fromY;
  const dist = Math.sqrt(dx * dx + dy * dy);
  if (dist === 0) return null;
  const angle = Math.atan2(dy, dx);
  // EC-7: clamp head length so it never exceeds 40% of the segment.
  const headLen = Math.min(HEAD_BASE_PX + strokeWidth * 2, dist * 0.4);
  const leftX = toX - headLen * Math.cos(angle - HEAD_ANGLE_RAD);
  const leftY = toY - headLen * Math.sin(angle - HEAD_ANGLE_RAD);
  const rightX = toX - headLen * Math.cos(angle + HEAD_ANGLE_RAD);
  const rightY = toY - headLen * Math.sin(angle + HEAD_ANGLE_RAD);
  return { apexX: toX, apexY: toY, leftX, leftY, rightX, rightY };
}

function lineBody(
  gen: RoughGenerator,
  el: LineElement | ArrowElement,
  seed: number,
): React.ReactNode[] {
  const opts = buildOptions(el, seed);
  const drawable = gen.line(el.x, el.y, el.to[0], el.to[1], opts);
  const dash = strokeDashArray(el.strokeStyle, el.strokeWidth ?? 1.5);
  return toRoughPaths(gen, drawable).map((p, i) => (
    <path
      // biome-ignore lint/suspicious/noArrayIndexKey: stable rough.js path order
      key={`body-${i}`}
      d={p.d}
      stroke={p.stroke}
      strokeWidth={p.strokeWidth}
      fill="none"
      strokeLinecap="round"
      strokeLinejoin="round"
      strokeDasharray={dash}
    />
  ));
}

function arrowHead(
  gen: RoughGenerator,
  fromX: number,
  fromY: number,
  toX: number,
  toY: number,
  seed: number,
  el: ArrowElement,
  side: "start" | "end",
): React.ReactNode[] {
  const geom = arrowHeadGeometry(fromX, fromY, toX, toY, el.strokeWidth ?? 1.5);
  if (!geom) return [];
  const opts = buildOptions(el, seed);
  // Two short rough-drawn segments forming the V.
  const leftDrawable = gen.line(geom.apexX, geom.apexY, geom.leftX, geom.leftY, opts);
  const rightDrawable = gen.line(geom.apexX, geom.apexY, geom.rightX, geom.rightY, opts);
  const leftPaths = toRoughPaths(gen, leftDrawable);
  const rightPaths = toRoughPaths(gen, rightDrawable);
  const nodes: React.ReactNode[] = [];
  for (const [i, p] of leftPaths.entries()) {
    nodes.push(
      <path
        key={`${side}-l-${i}`}
        d={p.d}
        stroke={p.stroke}
        strokeWidth={p.strokeWidth}
        fill="none"
        strokeLinecap="round"
        strokeLinejoin="round"
        data-line-part="arrowhead"
      />,
    );
  }
  for (const [i, p] of rightPaths.entries()) {
    nodes.push(
      <path
        key={`${side}-r-${i}`}
        d={p.d}
        stroke={p.stroke}
        strokeWidth={p.strokeWidth}
        fill="none"
        strokeLinecap="round"
        strokeLinejoin="round"
        data-line-part="arrowhead"
      />,
    );
  }
  return nodes;
}

export function renderLine(gen: RoughGenerator, el: LineElement): React.ReactNode {
  return <g opacity={el.opacity ?? 1}>{lineBody(gen, el, el.seed ?? 0)}</g>;
}

export function renderArrow(gen: RoughGenerator, el: ArrowElement): React.ReactNode {
  const seed = el.seed ?? 0;
  const nodes: React.ReactNode[] = [...lineBody(gen, el, seed)];
  if (el.headEnd !== false) {
    nodes.push(...arrowHead(gen, el.x, el.y, el.to[0], el.to[1], seed + 1, el, "end"));
  }
  if (el.headStart) {
    nodes.push(...arrowHead(gen, el.to[0], el.to[1], el.x, el.y, seed + 2, el, "start"));
  }
  let label: React.ReactNode = null;
  if (el.label) {
    const midX = (el.x + el.to[0]) / 2;
    const midY = (el.y + el.to[1]) / 2;
    // Offset perpendicular to the line so label doesn't sit on the stroke.
    const dx = el.to[0] - el.x;
    const dy = el.to[1] - el.y;
    const dist = Math.sqrt(dx * dx + dy * dy) || 1;
    const nx = -dy / dist;
    const ny = dx / dist;
    const offset = 12;
    label = (
      <text
        x={midX + nx * offset}
        y={midY + ny * offset}
        textAnchor="middle"
        dominantBaseline="central"
        fontSize={14}
        fontFamily="ui-sans-serif, system-ui, sans-serif"
        fill={el.stroke ?? "currentColor"}
        style={{ pointerEvents: "none" }}
      >
        {el.label}
      </text>
    );
  }
  return (
    <g opacity={el.opacity ?? 1}>
      {nodes}
      {label}
    </g>
  );
}

import { getStroke } from "perfect-freehand";
import type { FreedrawElement } from "@/components/ui/whiteboard/schema";

const DEFAULT_STROKE_OPTIONS = {
  size: 8,
  thinning: 0.5,
  smoothing: 0.5,
  streamline: 0.5,
};

function fmt(n: number | undefined): string {
  return typeof n === "number" && Number.isFinite(n) ? n.toFixed(2) : "0";
}

function svgPathFromStroke(points: number[][]): string {
  if (points.length === 0) return "";
  const first = points[0] ?? [];
  let d = `M ${fmt(first[0])} ${fmt(first[1])}`;
  for (let i = 1; i < points.length; i++) {
    const p = points[i] ?? [];
    d += ` L ${fmt(p[0])} ${fmt(p[1])}`;
  }
  d += " Z";
  return d;
}

export function renderFreedraw(el: FreedrawElement): React.ReactNode {
  const size = (el.strokeWidth ?? 1.5) * 5;
  const inputPoints = el.points.map(([x, y, pressure]) => {
    const tx = el.x + x;
    const ty = el.y + y;
    return pressure === undefined ? [tx, ty] : [tx, ty, pressure];
  });
  const stroke = getStroke(inputPoints, {
    ...DEFAULT_STROKE_OPTIONS,
    size,
  });
  const d = svgPathFromStroke(stroke as number[][]);
  return (
    <g opacity={el.opacity ?? 1}>
      <path d={d} fill={el.stroke ?? "currentColor"} stroke="none" />
    </g>
  );
}

import type { TextElement } from "@/components/ui/whiteboard/schema";

const FONT_STACKS: Record<NonNullable<TextElement["fontFamily"]>, string> = {
  sans: "ui-sans-serif, system-ui, sans-serif",
  serif: "ui-serif, Georgia, serif",
  mono: "ui-monospace, SFMono-Regular, Menlo, monospace",
  hand: '"Virgil", "Caveat", "Comic Sans MS", cursive',
};

function textAnchor(align: TextElement["align"]): "start" | "middle" | "end" {
  if (align === "center") return "middle";
  if (align === "right") return "end";
  return "start";
}

export function renderText(el: TextElement): React.ReactNode {
  const fontSize = el.fontSize ?? 18;
  const fontFamily = FONT_STACKS[el.fontFamily ?? "hand"];
  const anchor = textAnchor(el.align);
  const lines = el.text.split("\n");
  // dy: first tspan at 0, subsequent at fontSize * 1.2 line-height.
  return (
    <g opacity={el.opacity ?? 1}>
      <text
        x={el.x}
        y={el.y}
        textAnchor={anchor}
        dominantBaseline="hanging"
        fontSize={fontSize}
        fontFamily={fontFamily}
        fill={el.stroke ?? "currentColor"}
      >
        {lines.map((line, i) => (
          // biome-ignore lint/suspicious/noArrayIndexKey: text is split deterministically on '\n' so the line index is the most stable key.
          <tspan key={i} x={el.x} dy={i === 0 ? 0 : fontSize * 1.2}>
            {line}
          </tspan>
        ))}
      </text>
    </g>
  );
}

/**
 * Thin adapter over `roughjs` — converts a `Drawable` into the array of
 * `<path>` descriptors we render in SVG. The actual `rough.generator()`
 * instance is created once per scene and reused across elements.
 */
import type { Drawable, Options } from "roughjs/bin/core";
import type { RoughGenerator } from "roughjs/bin/generator";

export interface RoughPath {
  d: string;
  stroke: string;
  strokeWidth: number;
  fill?: string;
}

export type RoughOptions = Options;

/** Convert a rough.js Drawable into renderable SVG path descriptors. */
export function toRoughPaths(generator: RoughGenerator, drawable: Drawable): RoughPath[] {
  const paths = generator.toPaths(drawable);
  return paths.map((p) => ({
    d: p.d,
    stroke: p.stroke,
    strokeWidth: p.strokeWidth,
    fill: p.fill,
  }));
}

/**
 * Maps a `WhiteboardElement` style props onto rough.js `Options`.
 */
import type { Options } from "roughjs/bin/core";

interface StyleSource {
  stroke?: string;
  strokeWidth?: number;
  strokeStyle?: "solid" | "dashed" | "dotted";
  fill?: string;
  fillStyle?: "hachure" | "solid" | "cross-hatch" | "zigzag";
  opacity?: number;
  roughness?: number;
}

const DEFAULT_STROKE = "currentColor";

export function buildOptions(src: StyleSource, seed: number): Options {
  const o: Options = {
    seed,
    stroke: src.stroke ?? DEFAULT_STROKE,
    strokeWidth: src.strokeWidth ?? 1.5,
    roughness: src.roughness ?? 1.2,
  };
  if (src.strokeStyle === "dashed") o.strokeLineDash = [10, 6];
  else if (src.strokeStyle === "dotted") o.strokeLineDash = [2, 4];
  if (src.fill) o.fill = src.fill;
  if (src.fillStyle) o.fillStyle = src.fillStyle;
  return o;
}

/**
 * SVG `stroke-dasharray` value for a logical strokeStyle. rough.js's
 * `RoughGenerator.toPaths()` does NOT propagate `strokeLineDash` into the
 * returned `PathInfo` — only the canvas / direct-SVG backends apply it. We
 * must set the attribute ourselves on the rendered `<path>`. Returns
 * `undefined` for `solid` and any unknown value.
 */
export function strokeDashArray(
  strokeStyle: StyleSource["strokeStyle"],
  strokeWidth: number,
): string | undefined {
  if (strokeStyle === "dashed") {
    const dash = Math.max(8, strokeWidth * 6);
    const gap = Math.max(5, strokeWidth * 4);
    return `${dash} ${gap}`;
  }
  if (strokeStyle === "dotted") {
    // 1×strokeWidth dot, ~2×strokeWidth gap. Round end caps make these look
    // like dots instead of squares.
    return `${strokeWidth} ${strokeWidth * 2.5}`;
  }
  return undefined;
}

export { DEFAULT_STROKE };

import { useCallback, useEffect, useRef } from "react";
import type { ViewportControls } from "@/components/ui/whiteboard/viewport/use-viewport";

interface DragState {
  pointerId: number;
  lastX: number;
  lastY: number;
}

/** Attaches pan + zoom listeners to an SVG element. */
export function usePointerPan(
  ref: React.RefObject<SVGSVGElement | null>,
  viewport: ViewportControls,
  size: { width: number; height: number },
): {
  onPointerDown: (e: React.PointerEvent<SVGSVGElement>) => void;
  onPointerMove: (e: React.PointerEvent<SVGSVGElement>) => void;
  onPointerUp: (e: React.PointerEvent<SVGSVGElement>) => void;
  onPointerCancel: (e: React.PointerEvent<SVGSVGElement>) => void;
} {
  const dragRef = useRef<DragState | null>(null);
  const spaceHeldRef = useRef(false);

  // EC-2: wheel events on React's JSX onWheel are passive — `preventDefault`
  // does nothing, which causes the page to scroll while the user tries to
  // zoom. We must attach the wheel handler imperatively with `{passive:false}`.
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const handler = (e: WheelEvent) => {
      e.preventDefault();
      const rect = el.getBoundingClientRect();
      const localX = e.clientX - rect.left;
      const localY = e.clientY - rect.top;
      // Map screen-px → viewBox coords by ratio of rect to size.
      const scaleX = size.width / rect.width;
      const scaleY = size.height / rect.height;
      viewport.zoomAt(localX * scaleX, localY * scaleY, -e.deltaY * 0.001, size);
    };
    el.addEventListener("wheel", handler, { passive: false });
    return () => el.removeEventListener("wheel", handler);
  }, [ref, viewport, size]);

  // Track Space key for pan-with-any-button (Excalidraw "hand" mode).
  useEffect(() => {
    const down = (e: KeyboardEvent) => {
      if (e.code === "Space") spaceHeldRef.current = true;
    };
    const up = (e: KeyboardEvent) => {
      if (e.code === "Space") spaceHeldRef.current = false;
    };
    window.addEventListener("keydown", down);
    window.addEventListener("keyup", up);
    return () => {
      window.removeEventListener("keydown", down);
      window.removeEventListener("keyup", up);
    };
  }, []);

  const onPointerDown = useCallback((e: React.PointerEvent<SVGSVGElement>) => {
    // EC-10: only start drag when the down event is on our SVG, not on a
    // child rendered via portal/etc. event.currentTarget guarantees this.
    if (e.target instanceof Element && !e.currentTarget.contains(e.target)) return;
    // Left button (0) or middle (1) or Space-held pan.
    const isMouseButton = e.button === 0 || e.button === 1;
    if (!isMouseButton && e.pointerType === "mouse") return;
    if (e.pointerType === "mouse" && e.button !== 1 && !spaceHeldRef.current && e.button !== 0) {
      return;
    }
    dragRef.current = { pointerId: e.pointerId, lastX: e.clientX, lastY: e.clientY };
    e.currentTarget.setPointerCapture(e.pointerId);
  }, []);

  const onPointerMove = useCallback(
    (e: React.PointerEvent<SVGSVGElement>) => {
      const drag = dragRef.current;
      if (!drag || drag.pointerId !== e.pointerId) return;
      const dx = e.clientX - drag.lastX;
      const dy = e.clientY - drag.lastY;
      drag.lastX = e.clientX;
      drag.lastY = e.clientY;
      const el = ref.current;
      if (!el) return;
      const rect = el.getBoundingClientRect();
      const scaleX = size.width / rect.width;
      const scaleY = size.height / rect.height;
      viewport.pan(dx * scaleX, dy * scaleY);
    },
    [ref, viewport, size],
  );

  const releaseDrag = useCallback((e: React.PointerEvent<SVGSVGElement>) => {
    const drag = dragRef.current;
    if (!drag || drag.pointerId !== e.pointerId) return;
    try {
      e.currentTarget.releasePointerCapture(e.pointerId);
    } catch {
      // Already released — ignore.
    }
    dragRef.current = null;
  }, []);

  return {
    onPointerDown,
    onPointerMove,
    onPointerUp: releaseDrag,
    onPointerCancel: releaseDrag,
  };
}

/**
 * Viewport state and helpers — pan via (x, y) and zoom via a scalar.
 *
 * Coordinate system:
 *   - World space: where elements are defined (the JSON `x`, `y` etc.).
 *   - Screen space: the rendered SVG bounding box on the page.
 *   - viewBox: `${x} ${y} ${width/zoom} ${height/zoom}`. Increasing zoom
 *     SHRINKS the viewBox dimensions, magnifying the rendered content.
 *
 * `zoomAt(screenX, screenY, delta, viewportSize)` keeps the world point under
 * the cursor stable while zooming (see test for invariant).
 */
import { useCallback, useMemo, useState } from "react";

export const MIN_ZOOM = 0.1;
export const MAX_ZOOM = 8;

export interface ViewportState {
  x: number;
  y: number;
  zoom: number;
}

export interface ViewportSize {
  width: number;
  height: number;
}

export interface ViewportBounds {
  minX: number;
  minY: number;
  maxX: number;
  maxY: number;
}

export interface UseViewportOptions {
  width: number;
  height: number;
  initialZoom?: number;
  initialCenter?: [number, number];
}

export interface ViewportControls {
  state: ViewportState;
  pan: (dx: number, dy: number) => void;
  setZoom: (zoom: number) => void;
  zoomAt: (screenX: number, screenY: number, delta: number, size: ViewportSize) => void;
  reset: () => void;
  fitTo: (bounds: ViewportBounds, size: ViewportSize) => void;
  viewBox: (size: ViewportSize) => string;
}

function clampZoom(z: number): number {
  if (!Number.isFinite(z)) return 1;
  return Math.min(MAX_ZOOM, Math.max(MIN_ZOOM, z));
}

export function useViewport(opts: UseViewportOptions): ViewportControls {
  const initial: ViewportState = useMemo(() => {
    const zoom = clampZoom(opts.initialZoom ?? 1);
    if (opts.initialCenter) {
      // Position viewBox so initialCenter sits at the visual center.
      const [cx, cy] = opts.initialCenter;
      return {
        x: cx - opts.width / (2 * zoom),
        y: cy - opts.height / (2 * zoom),
        zoom,
      };
    }
    return { x: 0, y: 0, zoom };
  }, [opts.initialCenter, opts.initialZoom, opts.width, opts.height]);

  const [state, setState] = useState<ViewportState>(initial);

  const pan = useCallback((dx: number, dy: number) => {
    setState((prev) => ({ ...prev, x: prev.x - dx / prev.zoom, y: prev.y - dy / prev.zoom }));
  }, []);

  const setZoom = useCallback((zoom: number) => {
    setState((prev) => ({ ...prev, zoom: clampZoom(zoom) }));
  }, []);

  const zoomAt = useCallback(
    (screenX: number, screenY: number, delta: number, _size: ViewportSize) => {
      setState((prev) => {
        const oldZoom = prev.zoom;
        const newZoom = clampZoom(prev.zoom * Math.exp(delta));
        if (newZoom === oldZoom) return prev;
        // World coordinate currently under cursor.
        const worldX = prev.x + screenX / oldZoom;
        const worldY = prev.y + screenY / oldZoom;
        // After zoom, we want the same screen point to map to the same world point.
        // viewBox.x + (screenX / newZoom) === worldX  →  x = worldX - screenX/newZoom.
        return {
          x: worldX - screenX / newZoom,
          y: worldY - screenY / newZoom,
          zoom: newZoom,
        };
      });
    },
    [],
  );

  const reset = useCallback(() => setState(initial), [initial]);

  const fitTo = useCallback((bounds: ViewportBounds, size: ViewportSize) => {
    const bboxWidth = Math.max(1, bounds.maxX - bounds.minX);
    const bboxHeight = Math.max(1, bounds.maxY - bounds.minY);
    const zoomX = size.width / bboxWidth;
    const zoomY = size.height / bboxHeight;
    const zoom = clampZoom(Math.min(zoomX, zoomY));
    const cx = (bounds.minX + bounds.maxX) / 2;
    const cy = (bounds.minY + bounds.maxY) / 2;
    setState({
      x: cx - size.width / (2 * zoom),
      y: cy - size.height / (2 * zoom),
      zoom,
    });
  }, []);

  const viewBox = useCallback(
    (size: ViewportSize) =>
      `${state.x} ${state.y} ${size.width / state.zoom} ${size.height / state.zoom}`,
    [state],
  );

  return { state, pan, setZoom, zoomAt, reset, fitTo, viewBox };
}
